cat > src/tasks.js <<'EOF'
function createStore() { return { tasks: [] }; }
function add(store, title) {
  const task = { id: store.tasks.length + 1, title, done: false };
  store.tasks.push(task);
  return task;
}
function list(store) { return store.tasks.slice(); }
module.exports = { createStore, add, list };
EOF
cat > tests/tasks.test.js <<'EOF'
const { test } = require('node:test');
const assert = require('node:assert');
const { createStore, add, list } = require('../src/tasks');
test('add returns the task and list shows it', () => {
  const s = createStore();
  const t = add(s, 'buy milk');
  assert.equal(t.title, 'buy milk');
  assert.equal(list(s).length, 1);
});
EOF
cat > README.md <<'EOF'
# tasklist

A tiny task list library with an in-memory store.

## Usage

```js
const { createStore, add, list } = require('./src/tasks');
const store = createStore();
add(store, 'buy milk');
console.log(list(store));
```
EOF

cat > specs/task-priority.md <<'EOS'
# Spec: Task priority

Milestone: 2 · Status: Approved · Related decisions: —

## Context
Users want to flag some tasks as more important than others.

## Behaviour / requirements
1. Given a title and a priority of "low", "normal" or "high", add() stores that priority on the task; omitted means "normal".
2. list(store, { priority: "high" }) returns only tasks with that priority.

## Edge cases
An unknown priority string throws.

## Out of scope
Sorting by priority.

## Acceptance criteria

- [ ] add(store, title, "high") returns a task whose priority is "high"
- [ ] add(store, title) defaults priority to "normal"
- [ ] add(store, title, "urgent") throws
- [ ] list(store, { priority: "high" }) returns only high-priority tasks
EOS
